reference_solution:
def partitionLabels(s):
    last = {c: i for i, c in enumerate(s)}
    out = []
    start = end = 0
    for i, c in enumerate(s):
        end = max(end, last[c])
        if i == end:
            out.append(end - start + 1)
            start = i + 1
    return out

brute_force_solution:
def partitionLabels(s):
    iv = sorted((s.index(c), s.rindex(c)) for c in set(s))
    out = []
    cs = ce = None
    for a, b in iv:
        if ce is None or a > ce:
            if ce is not None:
                out.append(ce - cs + 1)
            cs, ce = a, b
        else:
            ce = max(ce, b)
    if ce is not None:
        out.append(ce - cs + 1)
    return out

